# function for creating list of colors

def colors(fur_color_list):
    unique_colors = []
    i = 0
    while (i<len(fur_color_list)):
        if fur_color_list[i] in unique_colors:
            i+=1
        else:
            unique_colors.append(fur_color_list[i])
            i+=1
    return unique_colors

# function to determine which shift squirrel is in

def shift(shift_string):
    if shift_string == 'AM':
        return True
    elif shift_string == 'PM':
        return False

#function to combo Approaching and indifferent

def squirrel_antics(approach_list,indifferent_list):
    antics = []
    for i in range(len(approach_list)):
        if approach_list[i] == 'True':
            antics.append("approaching")
        elif indifferent_list[i] == "True":
            antics.append('indifferent')
        else:
            antics.append('nan')
    return antics


