# combined function

def squirrel_data_summary(shift_list,color_list,approach_list,indifferent_list):
    antics_list = squirrel_antics(approach_list,indifferent_list)
    unique_color_list = colors(color_list)
    
    AM_count = 0
    PM_count = 0
    AM_approach_count = 0
    AM_indiff_count = 0
    PM_approach_count = 0
    PM_indiff_count = 0
    
    for i in range(len(shift_list)):
        if shift(shift_list[i]) == True:
            AM_count +=1
            if antics_list[i] == 'approaching':
                AM_approach_count += 1
            else:
                AM_indiff_count += 1

        else:
            PM_count+=1
            if antics_list[i] == 'indifferent':
                PM_approach_count += 1
            else:
                PM_indiff_count += 1
  
    AM_pct = (AM_count/len(antics_list))*100.
    PM_pct = (PM_count/len(antics_list))*100.

    AM_pct_app = (AM_approach_count/AM_count)*100.
    PM_pct_app = (PM_approach_count/PM_count)*100.   

    AM_pct_indf = (AM_indiff_count/AM_count)*100.
    PM_pct_indf = (PM_indiff_count/PM_count)*100.  

    return AM_pct, PM_pct, AM_pct_app, PM_pct_app, AM_pct_indf, PM_pct_indf, len(unique_color_list), unique_color_list



squirrel_data_summary(squirrel_shift,squirrel_primary_fur_color,squirrel_approach,squirrel_indifferent)


